use super::*;

/// The records that cannot land because main moved under them.
///
/// A CONFLICT IS ONE RECORD, and that is the difference this whole migration buys. It used to be a
/// 27 MB file with markers in it; it is now "lane wrote `x.rs` from main rev 5, main is at rev 7", with
/// base, ours and theirs all three still readable in the ledger.
pub fn lane_conflicts(conn: &Connection, lane: &str) -> Result<Vec<LaneChange>, String> {
    Ok(lane_changes(conn, lane)?.into_iter().filter(|c| c.conflicted).collect())
}
